function scaleLog(d0,d1,r0,r1){ const min=Math.max(d0,1e-9); const max=Math.max(d1,min*1.0000001); const l0=Math.log(min), l1=Math.log(max); const span=(l1-l0)||1; const rspan=(r1-r0); return (v)=> r0 + ((Math.log(Math.max(v,1e-9))-l0)/span)*rspan; }
function linePath(xs,ys){ let d=""; for(let i=0;i<xs.length;i++) d += (i===0?"M":"L") + xs[i].toFixed(2)+" "+ys[i].toFixed(2)+" "; return d; }

