    const p=close[i], d=dates[i];
    if(p>curPeak){
      if(curMinDd<0) episodes.push([curMinDd, curPeakDate, curPeak, curTroughDate, curTrough]);
      curPeak=p; curPeakDate=d; curTrough=p; curTroughDate=d; curMinDd=0;
    } else {
      const dd=p/curPeak-1;
      if(dd<curMinDd){ curMinDd=dd; curTrough=p; curTroughDate=d; }
    }
  }
  if(curMinDd<0) episodes.push([curMinDd, curPeakDate, curPeak, curTroughDate, curTrough]);
  episodes.sort((a,b)=> a[0]-b[0]);

  function windowMaxDd(start,end){
    const sub=[];
    for(let i=0;i<dates.length;i++){
      const dt=dates[i];
      if(dt>=start && dt<=end) sub.push([dt, close[i]]);
    }
    if(!sub.length) return null;
    let pk=sub[0][1], pkd=sub[0][0];
    let tr=sub[0][1], trd=sub[0][0];
    let best=0, bestPk=null, bestTr=null;
    for(const dp of sub){
      const d=dp[0]; const p=dp[1];
      if(p>pk){ pk=p; pkd=d; tr=p; trd=d; }
      if(p<tr){ tr=p; trd=d; }
      const dd=tr/pk-1;
      if(dd<best){ best=dd; bestPk=[pkd,pk]; bestTr=[trd,tr]; }
    }
    return [best,bestPk,bestTr];
  }

  const gfc=windowMaxDd(new Date("2007-01-01"), new Date("2009-12-31"));
  const covid=windowMaxDd(new Date("2020-02-01"), new Date("2020-12-31"));

  function decadeMetrics(startYear,endYear){
    const idx=[];
    for(let i=0;i<dates.length;i++){
      const y=dates[i].getFullYear();
      if(y>=startYear && y<=endYear) idx.push(i);
    }
    if(!idx.length) return null;
    const i0=idx[0], i1=idx[idx.length-1];
    const sd=dates[i0], ed=dates[i1];
    const sp=close[i0], ep=close[i1];
    const yrs=(ed-sd)/(1000*60*60*24*365.2425);
    const priceRet=ep/sp-1;
    const cagr=yrs>0? Math.pow(ep/sp,1/yrs)-1 : NaN;
    const r=[];
    for(let k=1;k<idx.length;k++) r.push(close[idx[k]]/close[idx[k-1]]-1);
    const m=r.reduce((a,b)=>a+b,0)/(r.length||1);
    const v=r.reduce((a,b)=>a+(b-m)*(b-m),0)/(r.length||1);
    const annVol=Math.sqrt(v)*Math.sqrt(252);
    let pk=close[i0], tr=close[i0], maxDd=0;
    for(const i of idx){
      const p=close[i];
      if(p>pk){ pk=p; tr=p; }
      if(p<tr) tr=p;
      const dd=tr/pk-1;
      if(dd<maxDd) maxDd=dd;
    }
    let divSum=0;
    for(const i of idx) divSum += dividends[i];
    const label = (endYear===startYear+9)? (String(startYear)+"s") : (String(startYear)+"–"+String(endYear));
    return {label, start: sd.toISOString().slice(0,10), end: ed.toISOString().slice(0,10), sp, ep, priceRet, cagr, annVol, maxDd, divSum};
  }

  const decades=[
    decadeMetrics(1972,1979),
    decadeMetrics(1980,1989),
    decadeMetrics(1990,1999),
    decadeMetrics(2000,2009),
    decadeMetrics(2010,2019),
    decadeMetrics(2020,2026)
  ].filter(Boolean);

  const lastByYear=new Map();
  for(let i=0;i<dates.length;i++) lastByYear.set(dates[i].getFullYear(), i);
  const yearsSorted=Array.from(lastByYear.keys()).sort((a,b)=>a-b);
  const annR=[];
  for(let j=1;j<yearsSorted.length;j++){
    const y=yearsSorted[j], py=yearsSorted[j-1];
    const p=close[lastByYear.get(y)], pp=close[lastByYear.get(py)];
    annR.push({year:y, r:p/pp-1});
  }
  let bestYear=annR[0], worstYear=annR[0];
  for(const a of annR){ if(a.r>bestYear.r) bestYear=a; if(a.r<worstYear.r) worstYear=a; }

  const divEvents=[];
  for(let i=0;i<dividends.length;i++) if(dividends[i]!==0) divEvents.push({date: dates[i].toISOString().slice(0,10), d: dividends[i]});

  const splitEvents=[];
  for(let i=0;i<splits.length;i++) if(splits[i]!==0) splitEvents.push({date: dates[i].toISOString().slice(0,10), s: splits[i]});

  const byMonth=new Map();
  for(let i=0;i<dates.length;i++){
    const d=dates[i];
    const key=d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0");
    const cur=byMonth.get(key)||{sum:0,n:0};
    cur.sum += volume[i];
    cur.n += 1;
    byMonth.set(key,cur);
  }
  const months=Array.from(byMonth.keys()).sort();
  const monVol=months.map(k=>({date:k+"-01", v:byMonth.get(k).sum/byMonth.get(k).n}));

  const topVol=volume.map((v,i)=>({v, i})).sort((a,b)=>b.v-a.v).slice(0,12)
    .map(o=>({date:dates[o.i].toISOString().slice(0,10), v:o.v, c:close[o.i]}));

  const buildStamp=new Date().toISOString().replace("T"," ").slice(0,19)+" UTC";
  const firstNzIdx=volume.findIndex(v=>v!==0);
  const firstNonzeroVol = firstNzIdx>=0 ? dates[firstNzIdx].toISOString().slice(0,10) : "N/A";

  return {
    dates, close, startDate, endDate, years, startClose, endClose, cum, cagr, annVol,
    maxDd, maxPeak, maxTrough, totalDiv, atl:[dates[minI], close[minI]], ath:[dates[maxI], close[maxI]],
    ddSeries, episodes: episodes.slice(0,10), gfc, covid, decades, annR, bestYear, worstYear,
    divEvents, splitEvents, monVol, topVol,
    zeroVol: volume.filter(v=>v===0).length,
    firstNonzeroVol,
    buildStamp,
  };
}

function addKpi(k,v){
  const div=document.createElement("div");
  div.className="kpi";
  div.innerHTML = "<div class='k'>"+k+"</div><div class='v'>"+v+"</div>";
  document.getElementById("kpiGrid").appendChild(div);
}

function drawPriceChart(series, useLog){
  const svg=document.getElementById("priceChart");
  svg.innerHTML="";
  const NS="http://www.w3.org/2000/svg";
  const W=1000,H=340,pad={l:60,r:16,t:14,b:36};
  const w=W-pad.l-pad.r, h=H-pad.t-pad.b;
  const prices=series.close;
  const dates=series.dates;
  const x=scaleLinear(0, prices.length-1, pad.l, pad.l+w);
  const pmin=Math.min.apply(null, prices), pmax=Math.max.apply(null, prices);
  const y=(useLog? scaleLog(pmin,pmax,pad.t+h,pad.t): scaleLinear(pmin,pmax,pad.t+h,pad.t));

  for(let k=0;k<=5;k++){
    const yy=pad.t+(h*k/5);
    const ln=document.createElementNS(NS,"line");
    ln.setAttribute("x1",pad.l); ln.setAttribute("x2",pad.l+w);
    ln.setAttribute("y1",yy); ln.setAttribute("y2",yy);
    ln.setAttribute("stroke","rgba(255,255,255,0.08)");
    svg.appendChild(ln);
  }

  const yearFirst=new Map();
  for(let i=0;i<dates.length;i++){
    const yr=dates[i].getFullYear();
    if(!yearFirst.has(yr)) yearFirst.set(yr,i);
  }
  const years=Array.from(yearFirst.keys()).sort((a,b)=>a-b);
  for(const yr of years){
    if(yr%10!==0 && yr!==years[0] && yr!==years[years.length-1]) continue;
    const i=yearFirst.get(yr);
    const xx=x(i);
    const ln=document.createElementNS(NS,"line");
    ln.setAttribute("x1",xx); ln.setAttribute("x2",xx);
    ln.setAttribute("y1",pad.t); ln.setAttribute("y2",pad.t+h);
    ln.setAttribute("stroke","rgba(255,255,255,0.06)");
    svg.appendChild(ln);

    const t=document.createElementNS(NS,"text");
    t.textContent=String(yr);
    t.setAttribute("x",xx); t.setAttribute("y",pad.t+h+24);
    t.setAttribute("fill","rgba(255,255,255,0.60)");
    t.setAttribute("font-size","11");
    t.setAttribute("font-family","ui-monospace, Menlo, Consolas, monospace");
    t.setAttribute("text-anchor","middle");
    svg.appendChild(t);
  }

  const xs=[], ys=[];
  for(let i=0;i<prices.length;i++){ xs.push(x(i)); ys.push(y(prices[i])); }
  const path=document.createElementNS(NS,"path");
  path.setAttribute("d", linePath(xs,ys));
  path.setAttribute("fill","none");
  path.setAttribute("stroke","rgba(102,217,255,0.95)");
  path.setAttribute("stroke-width","2");
  svg.appendChild(path);

  const title=document.createElementNS(NS,"text");
  title.textContent = useLog ? "AXP Close (log scale)" : "AXP Close (linear scale)";
  title.setAttribute("x",pad.l); title.setAttribute("y",pad.t+12);
  title.setAttribute("fill","rgba(255,255,255,0.80)");
  title.setAttribute("font-size","12");
  title.setAttribute("font-family","ui-monospace, Menlo, Consolas, monospace");
  svg.appendChild(title);
}

function drawDrawdownChart(ddSeries){
  const svg=document.getElementById("ddChart");
  svg.innerHTML="";
  const NS="http://www.w3.org/2000/svg";
  const W=1000,H=260,pad={l:60,r:16,t:14,b:28};
  const w=W-pad.l-pad.r, h=H-pad.t-pad.b;
  const x=scaleLinear(0, ddSeries.length-1, pad.l, pad.l+w);
  const y=scaleLinear(-1.0, 0.0, pad.t+h, pad.t);

  const levels=[-0.8,-0.6,-0.4,-0.2,0.0];
  for(const lv of levels){
    const yy=y(lv);
    const ln=document.createElementNS(NS,"line");
    ln.setAttribute("x1",pad.l); ln.setAttribute("x2",pad.l+w);
    ln.setAttribute("y1",yy); ln.setAttribute("y2",yy);
    ln.setAttribute("stroke","rgba(255,255,255,0.08)");
    svg.appendChild(ln);

    const t=document.createElementNS(NS,"text");
    t.textContent=Math.round(lv*100)+"%";
    t.setAttribute("x",pad.l-10); t.setAttribute("y",yy+4);
    t.setAttribute("fill","rgba(255,255,255,0.55)");
    t.setAttribute("font-size","11");
    t.setAttribute("font-family","ui-monospace, Menlo, Consolas, monospace");
    t.setAttribute("text-anchor","end");
    svg.appendChild(t);
  }

  const xs=[], ys=[];
  for(let i=0;i<ddSeries.length;i++){ xs.push(x(i)); ys.push(y(ddSeries[i])); }
  const dPath=linePath(xs,ys);
  const area=document.createElementNS(NS,"path");
  const d = dPath + "L " + (pad.l+w) + " " + y(-1) + " L " + pad.l + " " + y(-1) + " Z";
  area.setAttribute("d", d);
  area.setAttribute("fill","rgba(255,107,107,0.18)");
  area.setAttribute("stroke","rgba(255,107,107,0.65)");
  area.setAttribute("stroke-width","1.5");
  svg.appendChild(area);

  const title=document.createElementNS(NS,"text");
  title.textContent="Drawdown from running peak (daily closes)";
  title.setAttribute("x",pad.l); title.setAttribute("y",pad.t+12);
  title.setAttribute("fill","rgba(255,255,255,0.80)");
  title.setAttribute("font-size","12");
  title.setAttribute("font-family","ui-monospace, Menlo, Consolas, monospace");
  svg.appendChild(title);
}

function drawAnnualReturnsChart(annR){
  const svg=document.getElementById("annRetChart");
  svg.innerHTML="";
  const NS="http://www.w3.org/2000/svg";
  const W=1000,H=260,pad={l:60,r:16,t:14,b:28};
  const w=W-pad.l-pad.r, h=H-pad.t-pad.b;
  const vals=annR.map(d=>d.r);
  const vmin=Math.min.apply(null, vals), vmax=Math.max.apply(null, vals);
  const y=scaleLinear(vmin,vmax,pad.t+h,pad.t);
  const x=scaleLinear(0,annR.length,pad.l,pad.l+w);
  const y0=y(0);

  const ln=document.createElementNS(NS,"line");
  ln.setAttribute("x1",pad.l); ln.setAttribute("x2",pad.l+w);
  ln.setAttribute("y1",y0); ln.setAttribute("y2",y0);
  ln.setAttribute("stroke","rgba(255,255,255,0.10)");
  svg.appendChild(ln);

  const bw=w/annR.length;
  for(let i=0;i<annR.length;i++){
    const v=annR[i].r;
    const xx=x(i);
    const yv=y(v);
    const rect=document.createElementNS(NS,"rect");
    rect.setAttribute("x",xx+0.5);
    rect.setAttribute("width",Math.max(1,bw-1));
    rect.setAttribute("y",Math.min(y0,yv));
    rect.setAttribute("height",Math.abs(yv-y0));
    rect.setAttribute("fill", v>=0 ? "rgba(155,255,184,0.55)" : "rgba(255,107,107,0.55)");
    svg.appendChild(rect);
  }

  const title=document.createElementNS(NS,"text");
  title.textContent="Calendar-year returns (last close of year)";
  title.setAttribute("x",pad.l); title.setAttribute("y",pad.t+12);
  title.setAttribute("fill","rgba(255,255,255,0.80)");
  title.setAttribute("font-size","12");
  title.setAttribute("font-family","ui-monospace, Menlo, Consolas, monospace");
  svg.appendChild(title);
}

function drawVolumeChart(monVol){
  const svg=document.getElementById("volChart");
  svg.innerHTML="";
  const NS="http://www.w3.org/2000/svg";
  const W=1000,H=260,pad={l:60,r:16,t:14,b:28};
  const w=W-pad.l-pad.r, h=H-pad.t-pad.b;
  const vals=monVol.map(d=>d.v);
  const vmin=Math.min.apply(null, vals), vmax=Math.max.apply(null, vals);
  const x=scaleLinear(0,monVol.length-1,pad.l,pad.l+w);
  const y=scaleLinear(vmin,vmax,pad.t+h,pad.t);

  for(let k=0;k<=4;k++){
    const yy=pad.t+(h*k/4);
    const ln=document.createElementNS(NS,"line");
    ln.setAttribute("x1",pad.l); ln.setAttribute("x2",pad.l+w);
    ln.setAttribute("y1",yy); ln.setAttribute("y2",yy);
    ln.setAttribute("stroke","rgba(255,255,255,0.08)");
    svg.appendChild(ln);
  }

  const xs=[], ys=[];
  for(let i=0;i<monVol.length;i++){ xs.push(x(i)); ys.push(y(monVol[i].v)); }
  const path=document.createElementNS(NS,"path");
  path.setAttribute("d", linePath(xs,ys));
  path.setAttribute("fill","none");
  path.setAttribute("stroke","rgba(155,255,184,0.90)");
  path.setAttribute("stroke-width","2");
  svg.appendChild(path);

  const title=document.createElementNS(NS,"text");
  title.textContent="Monthly average trading volume";
  title.setAttribute("x",pad.l); title.setAttribute("y",pad.t+12);
  title.setAttribute("fill","rgba(255,255,255,0.80)");
  title.setAttribute("font-size","12");
  title.setAttribute("font-family","ui-monospace, Menlo, Consolas, monospace");
  svg.appendChild(title);
}

function render(){
  const s=compute();

  document.getElementById("metaBox").innerHTML = "Generated from <b>benchmark/data.csv</b><br/>Coverage: " + s.startDate.toISOString().slice(0,10) + " to " + s.endDate.toISOString().slice(0,10);
  document.getElementById("buildStamp").textContent = "Build timestamp (UTC): " + s.buildStamp;

  addKpi("Dataset Coverage", s.startDate.toISOString().slice(0,10) + " → " + s.endDate.toISOString().slice(0,10) + " (" + s.years.toFixed(2) + " years)");
  addKpi("Start Close", fmtPrice(s.startClose));
  addKpi("End Close", fmtPrice(s.endClose));
  addKpi("Cumulative Price Return", fmtPct(s.cum));
  addKpi("CAGR (Close)", fmtPct(s.cagr));
  addKpi("Maximum Drawdown", fmtPct(s.maxDd));
  addKpi("Annualized Volatility", fmtPct(s.annVol));
  addKpi("Total Dividends Paid (Sum)", fmtPrice(s.totalDiv));

  document.getElementById("execSummary").innerHTML = "From " + s.startDate.toISOString().slice(0,10) + " to " + s.endDate.toISOString().slice(0,10) + ", AXP’s closing price rose from " + fmtPrice(s.startClose) + " to " + fmtPrice(s.endClose) + ", a cumulative price return of <b>" + fmtPct(s.cum) + "</b> and a close-based CAGR of <b>" + fmtPct(s.cagr) + "</b>. Over the same span, the stock experienced a maximum peak-to-trough drawdown of <b>" + fmtPct(s.maxDd) + "</b>, illustrating that long-term compounding came with episodic but severe downside risk.";

  document.getElementById("atlAthBox").innerHTML = "<div class='pill'>All-time low</div> <b>" + fmtPrice(s.atl[1]) + "</b> on " + s.atl[0].toISOString().slice(0,10) + "<br/><div class='pill' style='margin-top:6px;'>All-time high</div> <b>" + fmtPrice(s.ath[1]) + "</b> on " + s.ath[0].toISOString().slice(0,10);

  const insights=[
    "All-time low close: " + fmtPrice(s.atl[1]) + " on " + s.atl[0].toISOString().slice(0,10) + ".",
    "All-time high close: " + fmtPrice(s.ath[1]) + " on " + s.ath[0].toISOString().slice(0,10) + ".",
    "Worst annual return: " + s.worstYear.year + " (" + fmtPct(s.worstYear.r) + ").",
    "Best annual return: " + s.bestYear.year + " (" + fmtPct(s.bestYear.r) + ").",
  ];
  document.getElementById("insightsList").innerHTML = insights.map(x=>"<li>"+x+"</li>").join("");

  function callout(name,w){
    if(!w) return "<li>"+name+": Not computable from data window.</li>";
    const dd=w[0], pk=w[1], tr=w[2];
    return "<li><b>"+name+"</b>: max drawdown " + fmtPct(dd) + " (peak " + pk[0].toISOString().slice(0,10) + " " + fmtPrice(pk[1]) + " → trough " + tr[0].toISOString().slice(0,10) + " " + fmtPrice(tr[1]) + ").</li>";
  }
  document.getElementById("riskCallouts").innerHTML = [
    callout("Global Financial Crisis window (2007–2009)", s.gfc),
    callout("COVID shock window (Feb–Dec 2020)", s.covid)
  ].join("");

  document.getElementById("ddCaption").textContent = "Worst observed drawdown: " + fmtPct(s.maxDd) + " (peak " + s.maxPeak[0].toISOString().slice(0,10) + " → trough " + s.maxTrough[0].toISOString().slice(0,10) + ").";

  document.getElementById("worstDdRows").innerHTML = s.episodes.map(e=>
    "<tr><td class='num'>" + fmtPct(e[0]) + "</td><td>" + e[1].toISOString().slice(0,10) + "</td><td class='num'>" + fmtPrice(e[2]) + "</td><td>" + e[3].toISOString().slice(0,10) + "</td><td class='num'>" + fmtPrice(e[4]) + "</td></tr>"
  ).join("");

  document.getElementById("volNote").textContent = "Volume shown as monthly average. Zero-volume rows: " + fmtInt(s.zeroVol) + ". First non-zero volume date: " + s.firstNonzeroVol + ".";
  document.getElementById("topVolRows").innerHTML = s.topVol.map(r=>
    "<tr><td>"+r.date+"</td><td class='num'>"+fmtInt(r.v)+"</td><td class='num'>"+fmtPrice(r.c)+"</td></tr>"
  ).join("");

  document.getElementById("divSummary").innerHTML = "Total dividends recorded (sum of <code>Dividends</code>): <b>" + fmtPrice(s.totalDiv) + "</b>. Dividend events: <b>" + fmtInt(s.divEvents.length) + "</b>.";
  const firstDiv=s.divEvents[0], lastDiv=s.divEvents[s.divEvents.length-1];
  document.getElementById("divBox").innerHTML = "<b>First dividend record:</b> " + (firstDiv?firstDiv.date:"N/A") + " (" + (firstDiv?fmtPrice(firstDiv.d):"N/A") + ")<br/><b>Most recent dividend record:</b> " + (lastDiv?lastDiv.date:"N/A") + " (" + (lastDiv?fmtPrice(lastDiv.d):"N/A") + ")";
  document.getElementById("splitRows").innerHTML = s.splitEvents.map(e=>"<tr><td>"+e.date+"</td><td class='num'>"+e.s+"</td></tr>").join("");

  document.getElementById("annCaption").textContent = "Computed using the last trading-day close each calendar year. Best year: " + s.bestYear.year + " (" + fmtPct(s.bestYear.r) + "). Worst year: " + s.worstYear.year + " (" + fmtPct(s.worstYear.r) + ").";

  document.getElementById("decadeRows").innerHTML = s.decades.map(d=>
    "<tr><td>"+d.label+"</td><td class='num'>"+d.start+"</td><td class='num'>"+d.end+"</td><td class='num'>"+fmtPrice(d.sp)+"</td><td class='num'>"+fmtPrice(d.ep)+"</td><td class='num'>"+fmtPct(d.priceRet)+"</td><td class='num'>"+fmtPct(d.cagr)+"</td><td class='num'>"+fmtPct(d.annVol)+"</td><td class='num'>"+fmtPct(d.maxDd)+"</td><td class='num'>"+fmtPrice(d.divSum)+"</td></tr>"
  ).join("");

  let useLog=false;
  const series={dates:s.dates, close:s.close};
  drawPriceChart(series, useLog);
  drawDrawdownChart(s.ddSeries);
  drawAnnualReturnsChart(s.annR);
  drawVolumeChart(s.monVol);

  document.getElementById("scaleLin").addEventListener("click", ()=>{
    useLog=false;
    document.getElementById("scaleLin").classList.add("active");
    document.getElementById("scaleLog").classList.remove("active");
    drawPriceChart(series, useLog);
  });
  document.getElementById("scaleLog").addEventListener("click", ()=>{
    useLog=true;
    document.getElementById("scaleLog").classList.add("active");
    document.getElementById("scaleLin").classList.remove("active");
    drawPriceChart(series, useLog);
  });
}

render();
</script>
</body>
</html>
