+      const ln = document.createElementNS(NS, 'line');
+      ln.setAttribute('x1', String(pad.l));
+      ln.setAttribute('x2', String(pad.l + w));
+      ln.setAttribute('y1', String(y));
+      ln.setAttribute('y2', String(y));
